from fractions import Fraction as F

FORMS = {
    "xy+k": (lambda x, y, z: z - x * y, lambda x, y, k: x * y + k),
    "x+y+k": (lambda x, y, z: z - x - y, lambda x, y, k: x + y + k),
    "(x+y)k": (lambda x, y, z: F(z, x + y), lambda x, y, k: (x + y) * k),
    "xyk": (lambda x, y, z: F(z, x * y), lambda x, y, k: x * y * k),
}
OTHERS = {0: (1, 2), 1: (0, 2), 2: (0, 1)}

def rules(triads):
    out = []
    for t, (i, j) in OTHERS.items():
        for name, (solve, make) in FORMS.items():
            ks = {solve(tr[i], tr[j], tr[t]) for tr in triads}
            if len(ks) == 1:
                out.append(("pos", t, i, j, make, ks.pop()))
    # chain rule: next = m * prev + c, fitted from the first triad
    a, b, c = triads[0]
    if b != a:
        m = F(c - b, b - a)
        q = b - m * a
        if all(tr[1] == m * tr[0] + q and tr[2] == m * tr[1] + q for tr in triads):
            out.append(("chain", m, q))
    return out

def holds(r, tr):
    if r[0] == "pos":
        _, t, i, j, make, k = r
        return tr[t] == make(tr[i], tr[j], k)
    _, m, q = r
    return tr[1] == m * tr[0] + q and tr[2] == m * tr[1] + q

def pick(triads, options):
    rs = rules(triads)
    assert rs
    return [lab for lab, tr in options.items() if any(holds(r, tr) for r in rs)]

# worked example 2024-09-09_1230_R04: (2,3,17), (5,2,21) -> first x second + 11
assert pick([(2, 3, 17), (5, 2, 21)],
            {"A": (3, 4, 23), "B": (5, 6, 72), "C": (2, 5, 42), "D": (1, 4, 17)}) == ["A"]
# 2024-09-09_1230_R16: middle = first x third x 3
assert pick([(18, 378, 7), (14, 210, 5)],
            {"A": (17, 272, 8), "B": (17, 204, 6), "C": (23, 230, 5), "D": (15, 405, 9)}) == ["D"]
# 2024-09-09_1230_R17: each term = 2 x previous + 1
assert pick([(16, 33, 67), (19, 39, 79)],
            {"A": (22, 45, 91), "B": (14, 27, 53), "C": (18, 36, 80), "D": (21, 45, 90)}) == ["A"]
# constructed: third = (first + second) x 4
assert pick([(3, 5, 32), (6, 1, 28)],
            {"A": (2, 7, 36), "B": (4, 4, 30), "C": (5, 2, 30), "D": (1, 8, 32)}) == ["A"]

P = lambda ch: ord(ch) - 64
L = lambda p: chr((p - 1) % 26 + 65)

def shifts(w, c):
    return [((P(b) - P(a) + 13) % 26) - 13 for a, b in zip(w, c)]

def infer(d):
    if len(set(d)) == 1:
        return lambda i: d[0]
    if len(d) > 2 and all(d[i] == d[i % 2] for i in range(len(d))):
        return lambda i: d[i % 2]
    s = d[1] - d[0]
    if all(d[i + 1] - d[i] == s for i in range(len(d) - 1)):
        return lambda i: d[0] + s * i
    return None

def apply(rule, w):
    return "".join(L(P(ch) + rule(i)) for i, ch in enumerate(w))

def learn(examples):
    rule = infer(shifts(*examples[0]))
    if rule is None or any(apply(rule, w) != c for w, c in examples):
        return None
    return rule

def solve(examples, target, options):
    rule = learn(examples)
    assert rule is not None
    return [lab for lab, v in options.items() if v == apply(rule, target)]

# worked example 2024-09-12_1600_R14: FISH:DKQJ :: POND:NQLF :: SIZE:?
assert shifts("FISH", "DKQJ") == [-2, 2, -2, 2]
assert solve([("FISH", "DKQJ"), ("POND", "NQLF")], "SIZE",
             {"A": "QGXG", "B": "UGXC", "C": "UKXC", "D": "QKXG"}) == ["D"]
# 2024-09-12_1600_R08: +13 on every letter
assert solve([("ALW", "NYJ"), ("CNY", "PAL")], "DEP", {"A": "QRD", "B": "QRC", "C": "SRC", "D": "SRD"}) == ["B"]
# constructed: increasing shifts +1, +2, +3, +4
assert solve([("ABCD", "BDFH"), ("WXYZ", "XZBD")], "MOON",
             {"A": "NQRR", "B": "NPQR", "C": "NQSR", "D": "OQRR"}) == ["A"]
